// <auto-generated/>
namespace Fanex.Tarus.Finance.Business.Transaction
{
    using System.Data;
    using Fanex.Tarus.Finance.Criteria;
    using Fanex.Tarus.Finance.Criteria.Transaction;
    using Fanex.Tarus.Finance.DataAccess.Transaction;
    using Fanex.Tarus.Finance.Entities;
    using Fanex.Tarus.Infrastructure.Extensions;

    public interface IFinanceTransferService
    {
        ResultDataTable UpdateMultiple(int userId, string fileName, int fileSize, string ip);
    }

    public class FinanceTransferService : IFinanceTransferService
    {
        private readonly IFinanceTransferAccess financeTransferAccess;

        public FinanceTransferService() : this(null)
        {
        }

        internal FinanceTransferService(IFinanceTransferAccess financeTransferAccess)
            => this.financeTransferAccess = financeTransferAccess ?? new FinanceTransferAccess();

        public ResultDataTable UpdateMultiple(int userId, string fileName, int fileSize, string ip)
        {
            if (userId <= 0 || fileSize <= 0 || string.IsNullOrEmpty(fileName))
            {
                return new ResultDataTable(100, "Param input is invalid!");
            }

            var criteria = new FinanceTransferMulUpdCriteria(userId, fileName, fileSize, ip);
            var customerTransferList = financeTransferAccess.GetCustomerTransferList(criteria);

            if (criteria.ErrCode != 0)
            {
                return new ResultDataTable(criteria.ErrCode, criteria.ErrMsg);
            }

            var success = CreateResultDataTable();
            var failure = CreateResultDataTable(true);

            foreach (var item in customerTransferList)
            {
                var result = UpdateMultiple(item);
                var dataTable = result.IsFailure ? failure : success;
                var drow = dataTable.NewRow();
                drow[0] = dataTable.Rows.Count + 1;
                drow[1] = item.FromUsername;
                drow[2] = item.ToUsername;
                drow[3] = item.Amount;
                drow[4] = item.ExchangeRate;
                drow[5] = item.Description;
                drow[6] = item.IsCollection;

                if (result.IsFailure)
                {
                    drow[7] = result.ErrorMessage;
                }

                dataTable.Rows.Add(drow);
            }

            WriteLog(userId, fileName, fileSize, ip, success.Rows.Count);

            return new ResultDataTable(0, string.Empty, success, failure);
        }

        private static DataTable CreateResultDataTable(bool isFailure = false)
        {
            var dataTable = new DataTable();
            dataTable.Columns.Add(new DataColumn("Seq", typeof(int)));
            dataTable.Columns.Add(new DataColumn("FromUserName", typeof(string)));
            dataTable.Columns.Add(new DataColumn("ToUserName", typeof(string)));
            dataTable.Columns.Add(new DataColumn("Amount", typeof(decimal)));
            dataTable.Columns.Add(new DataColumn("ExchangeRate", typeof(double)));
            dataTable.Columns.Add(new DataColumn("Description", typeof(string)));
            dataTable.Columns.Add(new DataColumn("IsCollection", typeof(bool)));

            if (isFailure)
            {
                dataTable.Columns.Add(new DataColumn("Reason", typeof(string)));
            }

            return dataTable;
        }

        private Result UpdateMultiple(CustomerTransfer param)
        {
            var fromSiteDB = ObjectDbExtensions.GetSiteDBConfigByCustId(param.FromCustId);
            var toSiteDB = ObjectDbExtensions.GetSiteDBConfigByUsername(param.ToUsername);

            if (fromSiteDB.SiteDBGroupID == toSiteDB.SiteDBGroupID)
            {
                return financeTransferAccess.ExecuteNonQuery(
                    new FinanceTransferBettransInsCriteria(param, fromSiteDB), fromSiteDB.AGIP);
            }

            // Step 1: transfer at SiteDB FROM
            var fromResult = financeTransferAccess.ExecuteNonQueryWithRefNo(
                new FinanceTransferBettransInsSiteDBCriteria(param, fromSiteDB),
                fromSiteDB.AGIP);

            if (fromResult.IsFailure)
            {
                return fromResult;
            }

            var refNo = fromResult.RefNo;
            // Step 2: transfer at SiteDB TO
            var toResult = financeTransferAccess.ExecuteNonQueryWithRefNo(
                new FinanceTransferBettransInsSiteDBCriteria(param, toSiteDB, refNo),
                toSiteDB.AGIP);

            if (toResult.IsFailure)
            {
                // Rollback step 1
                financeTransferAccess.ExecuteNonQuery(
                    new TransferRollbackSiteDBCriteria(
                        refNo.Value,
                        param.UserId,
                        param.IP,
                        fromSiteDB),
                    fromSiteDB.AGIP);
            }

            return toResult;
        }

        private Result WriteLog(int userId, string fileName, int fileSize, string ip, int totalUsers)
            => financeTransferAccess.ExecuteNonQuery(
                new FinanceTransferMulUpdWrtieLogCriteria(userId, fileName, fileSize, ip, totalUsers));
    }
}
